CREATE TABLE IF NOT EXISTS studio_current_material_classifications (material_id text NOT NULL REFERENCES studio_history_index(material_id), source_key text NOT NULL, semantics_key text NOT NULL, model_identity text NOT NULL, state text NOT NULL, snapshot jsonb, result jsonb, receipt_id bigint, job_id uuid, error text, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (material_id, source_key, semantics_key));
